#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <vector>
#include <cmath>
#include <cfloat>

__global__ void scaled_dot_product_attention_fp16(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ out,
    int B, int H, int S, int D) {

    int q_idx = blockIdx.x * blockDim.x + threadIdx.x;   // sequence position
    int h     = blockIdx.y;                              // head
    int b     = blockIdx.z;                              // batch
    if (q_idx >= S) return;

    const float scale = rsqrtf((float)D);   // 1/sqrt(D)

    // pointer to the query vector
    const half* q_ptr = Q + (((b * H) + h) * S + q_idx) * D;

    // ---------- max for numerical stability ----------
    float max_score = -FLT_MAX;
    for (int k = 0; k < S; ++k) {
        const half* k_ptr = K + (((b * H) + h) * S + k) * D;
        float dot = 0.0f;
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            dot += __half2float(q_ptr[d]) * __half2float(k_ptr[d]);
        }
        float scaled = dot * scale;
        if (scaled > max_score) max_score = scaled;
    }

    // ---------- sum of exp ----------
    float sum_exp = 0.0f;
    for (int k = 0; k < S; ++k) {
        const half* k_ptr = K + (((b * H) + h) * S + k) * D;
        float dot = 0.0f;
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            dot += __half2float(q_ptr[d]) * __half2float(k_ptr[d]);
        }
        float scaled = dot * scale;
        sum_exp += expf(scaled - max_score);
    }

    // ---------- compute weighted sum ----------
    // D is at most 1024 in the reference; we allocate a static buffer large enough.
    float out_acc[1024];
    #pragma unroll 4
    for (int d = 0; d < D; ++d) out_acc[d] = 0.0f;

    for (int k = 0; k < S; ++k) {
        const half* k_ptr = K + (((b * H) + h) * S + k) * D;
        const half* v_ptr = V + (((b * H) + h) * S + k) * D;
        float dot = 0.0f;
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            dot += __half2float(q_ptr[d]) * __half2float(k_ptr[d]);
        }
        float scaled = dot * scale;
        float weight = expf(scaled - max_score) / sum_exp;
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            out_acc[d] += weight * __half2float(v_ptr[d]);
        }
    }

    // ---------- write output ----------
    half* out_ptr = out + (((b * H) + h) * S + q_idx) * D;
    #pragma unroll 4
    for (int d = 0; d < D; ++d) {
        out_ptr[d] = __float2half(out_acc[d]);
    }
}

std::vector<torch::Tensor> scaled_dot_product_attention_cuda(
    torch::Tensor Q,
    torch::Tensor K,
    torch::Tensor V) {

    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);

    auto out = torch::empty_like(Q);

    const int threads = 128;
    dim3 blocks((S + threads - 1) / threads, H, B);

    scaled_dot_product_attention_fp16<<<blocks, threads>>>(
        reinterpret_cast<const half*>(Q.data_ptr()),
        reinterpret_cast<const half*>(K.data_ptr()),
        reinterpret_cast<const half*>(V.data_ptr()),
        reinterpret_cast<half*>(out.data_ptr()),
        B, H, S, D);

    return {out};
}

