    m.def("scaled_dot_product_attention_cuda",
          &scaled_dot_product_attention_cuda,
          "Scaled Dot‑Product Attention (CUDA, fp16)");
}
'''

# compile the extension
_sdpa = load_inline(name='sdpa_ext',
